import{_ as s,o as t,c as n,ag as e}from"./chunks/framework.VvOSaRrC.js";const g=JSON.parse('{"title":"구조화된 태스크 포맷","description":"","frontmatter":{},"headers":[],"relativePath":"ko/task-format.md","filePath":"ko/task-format.md"}'),p={name:"ko/task-format.md"};function d(o,a,i,r,l,h){return t(),n("div",null,[...a[0]||(a[0]=[e(`<h1 id="구조화된-태스크-포맷" tabindex="-1">구조화된 태스크 포맷 <a class="header-anchor" href="#구조화된-태스크-포맷" aria-label="Permalink to &quot;구조화된 태스크 포맷&quot;">​</a></h1><blockquote><p>5필드 구조와 품질 체크포인트를 사용한 체계적 태스크 분해 방법입니다.</p></blockquote><h2 id="개요" tabindex="-1">개요 <a class="header-anchor" href="#개요" aria-label="Permalink to &quot;개요&quot;">​</a></h2><p>KRoot-ADK의 모든 구현 태스크는 명확한 완료 기준을 가진 구조화된 단위로 분해할 수 있습니다. 이 포맷은 누락 방지, 진행 상황 추적, 정기적 품질 검증을 보장합니다.</p><hr><h2 id="태스크-구조-5필드" tabindex="-1">태스크 구조 (5필드) <a class="header-anchor" href="#태스크-구조-5필드" aria-label="Permalink to &quot;태스크 구조 (5필드)&quot;">​</a></h2><p>각 태스크는 다음 필수 형식을 따릅니다:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>### Task N: [제목]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Do:        무엇을 구현할 것인가 (구체적 행동)</span></span>
<span class="line"><span>Files:     어떤 파일을 생성/수정할 것인가</span></span>
<span class="line"><span>Done when: 측정 가능한 완료 기준</span></span>
<span class="line"><span>Verify:    완료를 어떻게 검증할 것인가 (테스트 명령, 수동 확인)</span></span>
<span class="line"><span>Commit:    완료 시 커밋 메시지</span></span></code></pre></div><h3 id="필드-설명" tabindex="-1">필드 설명 <a class="header-anchor" href="#필드-설명" aria-label="Permalink to &quot;필드 설명&quot;">​</a></h3><table tabindex="0"><thead><tr><th>필드</th><th>필수</th><th>설명</th></tr></thead><tbody><tr><td><strong>Do</strong></td><td>예</td><td>단일, 실행 가능한 구현 단계</td></tr><tr><td><strong>Files</strong></td><td>예</td><td>명시적 파일 경로 (생성/수정/삭제)</td></tr><tr><td><strong>Done when</strong></td><td>예</td><td>측정 가능한 기준 (테스트 통과, 빌드 성공, 출력 일치)</td></tr><tr><td><strong>Verify</strong></td><td>예</td><td>구체적 검증 명령 또는 확인 방법</td></tr><tr><td><strong>Commit</strong></td><td>예</td><td>컨벤셔널 커밋 메시지 (feat/fix/refactor/test/docs)</td></tr></tbody></table><h3 id="예시" tabindex="-1">예시 <a class="header-anchor" href="#예시" aria-label="Permalink to &quot;예시&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>### Task 1: 사용자 인증 API 생성</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Do:        POST /api/auth/login 엔드포인트를 JWT 토큰 생성과 함께 구현</span></span>
<span class="line"><span>Files:     src/api/auth/login.ts (생성), src/types/auth.ts (생성)</span></span>
<span class="line"><span>Done when: POST /api/auth/login이 올바른 자격증명에 200+JWT, 잘못된 경우 401 반환</span></span>
<span class="line"><span>Verify:    npm test -- --grep &quot;auth login&quot; 통과</span></span>
<span class="line"><span>Commit:    feat(auth): add login endpoint with JWT generation</span></span></code></pre></div><hr><h2 id="품질-체크포인트-verify" tabindex="-1">품질 체크포인트 ([VERIFY]) <a class="header-anchor" href="#품질-체크포인트-verify" aria-label="Permalink to &quot;품질 체크포인트 ([VERIFY])&quot;">​</a></h2><p>구현 태스크 2-3개마다 <code>[VERIFY]</code> 체크포인트 태스크를 삽입합니다.</p><h3 id="형식" tabindex="-1">형식 <a class="header-anchor" href="#형식" aria-label="Permalink to &quot;형식&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>### Task N: [VERIFY] 품질 체크포인트</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Do:        전체 검증 스위트 실행</span></span>
<span class="line"><span>Files:     (없음 - 검증만)</span></span>
<span class="line"><span>Done when: 모든 검사가 에러 없이 통과</span></span>
<span class="line"><span>Verify:</span></span>
<span class="line"><span>  - 빌드 통과 (에러 제로)</span></span>
<span class="line"><span>  - 테스트 통과 (전체 그린)</span></span>
<span class="line"><span>  - 린트 클린 (경고 제로)</span></span>
<span class="line"><span>  - 수동: 기능이 예상대로 동작</span></span>
<span class="line"><span>Commit:    (커밋 없음 - 체크포인트만)</span></span></code></pre></div><h3 id="체크포인트-규칙" tabindex="-1">체크포인트 규칙 <a class="header-anchor" href="#체크포인트-규칙" aria-label="Permalink to &quot;체크포인트 규칙&quot;">​</a></h3><table tabindex="0"><thead><tr><th>규칙</th><th>설명</th></tr></thead><tbody><tr><td><strong>빈도</strong></td><td>태스크 2-3개마다 [VERIFY] 삽입</td></tr><tr><td><strong>블로킹</strong></td><td>체크포인트 실패 시 다음 태스크 진행 불가</td></tr><tr><td><strong>수정 우선</strong></td><td>계속하기 전에 수정 태스크 생성</td></tr><tr><td><strong>생략 불가</strong></td><td>[VERIFY] 태스크는 건너뛸 수 없음</td></tr><tr><td><strong>마지막</strong></td><td>항상 마지막에 [VERIFY] 삽입</td></tr></tbody></table><h3 id="삽입-패턴" tabindex="-1">삽입 패턴 <a class="header-anchor" href="#삽입-패턴" aria-label="Permalink to &quot;삽입 패턴&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Task 1: 구현</span></span>
<span class="line"><span>Task 2: 구현</span></span>
<span class="line"><span>Task 3: 구현</span></span>
<span class="line"><span>Task 4: [VERIFY] 품질 체크포인트     ← 3개 후</span></span>
<span class="line"><span>Task 5: 구현</span></span>
<span class="line"><span>Task 6: 구현</span></span>
<span class="line"><span>Task 7: [VERIFY] 품질 체크포인트     ← 2개 후</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>Task N: [VERIFY] 최종 체크포인트     ← 항상 마지막에</span></span></code></pre></div><hr><h2 id="ddd-태스크-변형" tabindex="-1">DDD 태스크 변형 <a class="header-anchor" href="#ddd-태스크-변형" aria-label="Permalink to &quot;DDD 태스크 변형&quot;">​</a></h2><p>기존 코드 작업 시 (DDD 워크플로우) ANALYZE/PRESERVE/IMPROVE 접두사 사용:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Task 1: [ANALYZE] 현재 인증 흐름 파악</span></span>
<span class="line"><span>Task 2: [PRESERVE] 특성화 테스트 추가</span></span>
<span class="line"><span>Task 3: [IMPROVE] JWT 기반 인증으로 리팩토링</span></span>
<span class="line"><span>Task 4: [VERIFY] 품질 체크포인트</span></span></code></pre></div><hr><h2 id="태스크-크기-가이드라인" tabindex="-1">태스크 크기 가이드라인 <a class="header-anchor" href="#태스크-크기-가이드라인" aria-label="Permalink to &quot;태스크 크기 가이드라인&quot;">​</a></h2><table tabindex="0"><thead><tr><th>크기</th><th>설명</th><th>예시</th></tr></thead><tbody><tr><td><strong>XS</strong></td><td>단일 함수/메서드</td><td>유효성 검증 헬퍼 추가</td></tr><tr><td><strong>S</strong></td><td>단일 파일 변경</td><td>API 엔드포인트 생성</td></tr><tr><td><strong>M</strong></td><td>2-3개 파일 변경</td><td>기능 + 테스트</td></tr><tr><td><strong>L</strong></td><td>4개+ 파일 변경</td><td><strong>더 작은 태스크로 분할</strong></td></tr></tbody></table><p><strong>규칙</strong>: 태스크가 3개 이상의 파일을 수정하면, 더 작은 태스크로 분할합니다.</p><hr><h2 id="todowrite-연동" tabindex="-1">TodoWrite 연동 <a class="header-anchor" href="#todowrite-연동" aria-label="Permalink to &quot;TodoWrite 연동&quot;">​</a></h2><p>모든 태스크는 TodoWrite를 통해 실시간 추적됩니다:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>태스크 발견   → TodoWrite: &quot;pending&quot; 상태로 추가</span></span>
<span class="line"><span>태스크 시작   → TodoWrite: &quot;in_progress&quot;로 변경</span></span>
<span class="line"><span>태스크 완료   → TodoWrite: &quot;completed&quot;로 변경</span></span>
<span class="line"><span>[VERIFY] 실패 → TodoWrite: 수정 태스크를 &quot;pending&quot;으로 추가</span></span></code></pre></div><hr><h2 id="워크플로우와의-연동" tabindex="-1">워크플로우와의 연동 <a class="header-anchor" href="#워크플로우와의-연동" aria-label="Permalink to &quot;워크플로우와의 연동&quot;">​</a></h2><table tabindex="0"><thead><tr><th>워크플로우</th><th>태스크 포맷 활용 방법</th></tr></thead><tbody><tr><td><strong>POC-First</strong></td><td>각 단계에서 이 형식으로 태스크 생성</td></tr><tr><td><strong>TDD</strong></td><td>RED-GREEN-REFACTOR가 태스크 시퀀스로 매핑</td></tr><tr><td><strong>DDD</strong></td><td>ANALYZE-PRESERVE-IMPROVE가 태스크 접두사로 매핑</td></tr><tr><td><strong>Ralph Loop</strong></td><td>루프 반복에서 TodoWrite로 진행 추적</td></tr></tbody></table><hr><h2 id="관련-문서" tabindex="-1">관련 문서 <a class="header-anchor" href="#관련-문서" aria-label="Permalink to &quot;관련 문서&quot;">​</a></h2><ul><li><a href="./poc-first.html">POC-First 워크플로우</a> — 단계별 Greenfield 개발</li><li><a href="./pr-lifecycle.html">PR 라이프사이클 자동화</a> — PR 관리 자동화</li><li><a href="./tdd-ddd.html">TDD &amp; DDD 워크플로우</a> — 대안 개발 방법론</li></ul>`,39)])])}const u=s(p,[["render",d]]);export{g as __pageData,u as default};
